import itertools

def get_m(edges, n, j_size):
    # edges is a list of (u, v)
    # n is number of vertices
    # j_size is size of subset J
    max_e = 0
    for subset in itertools.combinations(range(n), j_size):
        subset_set = set(subset)
        count = 0
        for u, v in edges:
            if u in subset_set and v in subset_set:
                count += 1
        if count > max_e:
            max_e = count
    return max_e

def solve():
    N = 15
    X_size = 56
    I_size = 7
    J_size = 8

    max_v = 0
    # We'll try some common graphs
    # 1. Complete bipartite K_{a, b}
    for a in range(1, N):
        b = N - a
        edges = []
        for i in range(a):
            for j in range(a, N):
                edges.append((i, j))

        E_size = len(edges)
        # We need 15y + E_size <= 56
        for y in range((56 - E_size) // 15 + 1):
            if E_size <= 56:
                m = get_m(edges, N, J_size)
                v = 7 * y + E_size - m
                if v > max_v:
                    max_v = v

    # 2. Disjoint cliques
    # Try all partitions of 15 into clique sizes
    from itertools import combinations

    def partitions(n, min_val=1):
        if n == 0:
            yield []
            return
        for i in range(min_val, n + 1):
            for p in partitions(n - i, i):
                yield [i] + p

    for p in partitions(N):
        edges = []
        current_v = 0
        for size in p:
            for i in range(size):
                for j in range(i + 1, size):
                    edges.append((current_v + i, current_v + j))
            current_v += size

        E_size = len(edges)
        for y in range((56 - E_size) // 15 + 1):
            if E_size <= 56:
                m = get_m(edges, N, J_size)
                v = 7 * y + E_size - m
                if v > max_v:
                    max_v = v

    # 3. Regular graphs? Too many. Let's try cycles or something.
    # 4. Just random graphs?
    import random
    for _ in range(1000):
        E_target = random.randint(0, 56)
        edges = []
        all_possible_edges = list(itertools.combinations(range(N), 2))
        random.shuffle(all_possible_edges)
        edges = all_possible_edges[:E_target]

        for y in range((56 - E_target) // 15 + 1):
            if E_target <= 56:
                m = get_m(edges, N, J_size)
                v = 7 * y + E_target - m
                if v > max_v:
                    max_v = v
    return max_v

print(solve())
